package render

import (
	"fmt"
	"strings"

	"github.com/elliot/terraform-provider-netbox/internal/gen/model"
)

const generatedHeader = "// Code generated by internal/gen from the NetBox %s OpenAPI document. DO NOT EDIT.\n\n"

// commonImports is the superset of imports generated files may need; unused
// ones are pruned by goimports processing.
const commonImports = `import (
	"context"
	"fmt"
	"net/url"
	"regexp"
	"strconv"

	"github.com/hashicorp/terraform-plugin-framework-jsontypes/jsontypes"
	"github.com/hashicorp/terraform-plugin-framework-timetypes/timetypes"
	"github.com/hashicorp/terraform-plugin-framework-validators/int64validator"
	"github.com/hashicorp/terraform-plugin-framework-validators/listvalidator"
	"github.com/hashicorp/terraform-plugin-framework-validators/setvalidator"
	"github.com/hashicorp/terraform-plugin-framework-validators/stringvalidator"
	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/datasource"
	dsschema "github.com/hashicorp/terraform-plugin-framework/datasource/schema"
	"github.com/hashicorp/terraform-plugin-framework/diag"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/identityschema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/boolplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/float64planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/int64planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/listdefault"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/listplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/setdefault"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/setplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringdefault"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/schema/validator"
	"github.com/hashicorp/terraform-plugin-framework/types"

	"github.com/elliot/terraform-provider-netbox/internal/conv"
	"github.com/elliot/terraform-provider-netbox/internal/customfields"
	"github.com/elliot/terraform-provider-netbox/internal/provider"
	"github.com/elliot/terraform-provider-netbox/netbox"
)

`

// resourceFile renders <name>_resource.go.
func resourceFile(r *model.Resource, version string) (string, error) {
	var b strings.Builder
	fmt.Fprintf(&b, generatedHeader, version)
	fmt.Fprintf(&b, "package %s\n\n", pkgName(r.App))
	b.WriteString(commonImports)

	g, lg := r.GoName, lower(r.GoName)
	fmt.Fprintf(&b, "func init() { provider.RegisterResource(New%sResource) }\n\n", g)
	b.WriteString(enumVars(r))
	fmt.Fprintf(&b, "// %sModel is the Terraform state of %s.\n", g, r.TFType())
	b.WriteString(modelStruct(g+"Model", r.Attrs))
	b.WriteString(nestedTypes(r, r.Attrs))

	fmt.Fprintf(&b, `var (
	_ resource.Resource                = &%[1]sResource{}
	_ resource.ResourceWithConfigure   = &%[1]sResource{}
	_ resource.ResourceWithImportState = &%[1]sResource{}
	_ resource.ResourceWithIdentity    = &%[1]sResource{}
)

// %[1]sResource manages %[2]s objects (%[3]s).
type %[1]sResource struct {
	client *netbox.APIClient
	cf     *customfields.Cache
}

// New%[1]sResource returns a new %[2]s resource.
func New%[1]sResource() resource.Resource { return &%[1]sResource{} }

func (r *%[1]sResource) Metadata(_ context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + %[4]q
}

func (r *%[1]sResource) Schema(_ context.Context, _ resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = schema.Schema{
		MarkdownDescription: %[5]s,
		Attributes: %[6]sResourceAttributes(),
	}
}

func (r *%[1]sResource) IdentitySchema(_ context.Context, _ resource.IdentitySchemaRequest, resp *resource.IdentitySchemaResponse) {
	resp.IdentitySchema = identityschema.Schema{
		Attributes: map[string]identityschema.Attribute{
			"id": identityschema.Int64Attribute{RequiredForImport: true, Description: "NetBox object ID."},
		},
	}
}

func (r *%[1]sResource) Configure(_ context.Context, req resource.ConfigureRequest, resp *resource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}
	pd, ok := req.ProviderData.(*provider.ProviderData)
	if !ok {
		resp.Diagnostics.AddError("Unexpected provider data", fmt.Sprintf("expected *provider.ProviderData, got %%T", req.ProviderData))
		return
	}
	r.client = pd.API
	r.cf = pd.CustomFields
}

`, g, r.TFType(), r.Path, "_"+r.Name, q(resourceDescription(r)), lg)

	// Schema attributes.
	fmt.Fprintf(&b, "// %sResourceAttributes returns the schema attributes of %s.\nfunc %sResourceAttributes() map[string]schema.Attribute {\nreturn map[string]schema.Attribute{\n", lg, r.TFType(), lg)
	for _, a := range r.Attrs {
		b.WriteString(schemaAttr(r, a, "schema", false, false, ""))
	}
	b.WriteString("}\n}\n\n")

	// CRUD.
	cfArg := ""
	if r.HasCustomFields {
		cfArg = "r.cf, "
	}
	invalidate := ""
	if r.Path == "/api/extras/custom-fields/" {
		invalidate = "\tr.cf.Invalidate() // definitions changed\n"
	}
	fmt.Fprintf(&b, `func (r *%[1]sResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var plan %[1]sModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	if resp.Diagnostics.HasError() {
		return
	}
	body := %[2]sToCreate(ctx, &plan, %[8]s&resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	obj, res, err := r.client.%[3]s.%[4]sCreate(ctx).%[5]s(*body).Execute()
	if err != nil {
		resp.Diagnostics.AddError("Error creating %[6]s", netbox.WrapError(err, res).Error())
		return
	}
%[9]s
	var state %[1]sModel
	%[2]sFromAPI(ctx, obj, &plan, &state, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &state)...)
	provider.SetIdentityID(ctx, resp.Identity, state.Id, &resp.Diagnostics)
}

func (r *%[1]sResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	var state %[1]sModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	id, err := netbox.Int32ID(state.Id.ValueInt64())
	if err != nil {
		resp.Diagnostics.AddError("Invalid ID", err.Error())
		return
	}
	obj, res, err := r.client.%[3]s.%[4]sRetrieve(ctx, id).Execute()
	if err != nil {
		if werr := netbox.WrapError(err, res); netbox.IsNotFound(werr) {
			resp.State.RemoveResource(ctx)
			return
		} else {
			resp.Diagnostics.AddError("Error reading %[6]s", werr.Error())
			return
		}
	}
	prior := state
	%[2]sFromAPI(ctx, obj, &prior, &state, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &state)...)
	provider.SetIdentityID(ctx, resp.Identity, state.Id, &resp.Diagnostics)
}

func (r *%[1]sResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var plan, state %[1]sModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	id, err := netbox.Int32ID(state.Id.ValueInt64())
	if err != nil {
		resp.Diagnostics.AddError("Invalid ID", err.Error())
		return
	}
	body := %[2]sToPatch(ctx, &plan, &state, %[8]s&resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	obj, res, err := r.client.%[3]s.%[4]sPartialUpdate(ctx, id).%[7]s(*body).Execute()
	if err != nil {
		resp.Diagnostics.AddError("Error updating %[6]s", netbox.WrapError(err, res).Error())
		return
	}
%[9]s
	var out %[1]sModel
	%[2]sFromAPI(ctx, obj, &plan, &out, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &out)...)
	provider.SetIdentityID(ctx, resp.Identity, out.Id, &resp.Diagnostics)
}

func (r *%[1]sResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var state %[1]sModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	id, err := netbox.Int32ID(state.Id.ValueInt64())
	if err != nil {
		resp.Diagnostics.AddError("Invalid ID", err.Error())
		return
	}
	res, err := r.client.%[3]s.%[4]sDestroy(ctx, id).Execute()
	if err != nil {
		if werr := netbox.WrapError(err, res); !netbox.IsNotFound(werr) {
			resp.Diagnostics.AddError("Error deleting %[6]s", werr.Error())
		}
	}
%[9]s}

func (r *%[1]sResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	provider.ImportInt64ID(ctx, req, resp)
}

`, g, lg, r.Service, r.OpPrefix, r.CreateType, r.TFType(), r.PatchType, cfArg, invalidate)

	// Conversions.
	create, err := toAPIFunc(r, false)
	if err != nil {
		return "", err
	}
	patch, err := toAPIFunc(r, true)
	if err != nil {
		return "", err
	}
	b.WriteString(create)
	b.WriteString(patch)
	b.WriteString(fromAPIFunc(r, false))
	return b.String(), nil
}

func resourceDescription(r *model.Resource) string {
	d := r.Description
	if d == "" {
		d = strings.ReplaceAll(r.Name, "_", " ") + " objects"
	}
	d = strings.TrimSuffix(strings.TrimSpace(d), ".")
	return fmt.Sprintf("Manages a NetBox %s (`%s`).", strings.TrimSuffix(strings.TrimSuffix(d, " objects"), " object"), r.Path)
}

// pkgName is the Go package name for an app.
func pkgName(app string) string { return strings.ReplaceAll(app, "-", "") }
